    // ------------------------------------------------------------------
    // Schedule for initialization
    //
    // Do a row-major traversal (j is x, i is y), vectorized along j and
    // parallelized across i. This keeps writes contiguous in memory and
    // uses all cores during the one-time initialization.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    init_A
        .compute_root()
        .parallel(i)          // parallel over rows
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_A.realize(A, target);
    init_B.realize(B, target);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n       = N;
    int tsteps  = TSTEPS;

    // Buffers corresponding to A[N][N] and B[N][N].
    // C layout is A[i][j]; we map that to A_buf(j, i).
    Halide::Buffer<num_t, 2> A(n, n);  // x = j, y = i
    Halide::Buffer<num_t, 2> B(n, n);  // x = j, y = i

    // Initialize A and B.
    init_array(n, A, B);

    // -------------------------------
    // Define the Jacobi 2D stencil in Halide
    // -------------------------------

    // ImageParam representing the "current" grid (either A or B).
    ImageParam cur_param(type_of<num_t>(), 2, "cur_param");

    // Vars: x corresponds to column index j, y to row index i.
    Var x("x"), y("y");

    // Factor 0.2 in the correct type.
    Expr w = cast<num_t>(Expr(0.2));

    // Jacobi update:
    //
    // B[i][j] = 0.2 * (A[i][j] +
