    const int vec_width = target.natural_vector_size<num_t>();

    // Tunable tile sizes; chosen to give tiles that fit comfortably in cache.
    const int tile_x = 64;
    const int tile_y = 32;

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    jacobi
        .compute_root()
        // x, y are logical coordinates; we know we will only realize on
        // [1 .. n-2] in each dimension.
        .bound(x, 1, n - 2)
        .bound(y, 1, n - 2)
        // Tile into cache‑friendly blocks.
